// page/02-scope.js
// The apply surface and the controls that belong to it.
// Generated by linkedin/automation/scripts/split-page-helpers.py from 00-context.js.

Object.assign(helpers, {
      // A job card of the results list, by id. LinkedIn has shipped both a
      // button card and an anchor card for the same job, and the list unmounts
      // cards while it scrolls. The card is a shortcut, not a requirement.
      jobCard(jobId) {
        const button = document.querySelector(`[role="button"][componentkey*="${jobId}"]`);
        if (button && helpers.painted(button)) return button;
        return document.querySelector(`a[href*="/jobs/view/${jobId}"]`);
      },
      // The results list has its own "Next" for pagination. A control that
      // lives inside the list is never a control of the form.
      inResultsList(node, scope) {
        // The apply surface can contain card-shaped rows of its own (resume
        // entries). Inside the form, a control is always a control of the form.
        if (scope && scope.contains(node)) return false;
        let current = node;
        while (current && current !== document.body) {
          if (scope && current === scope) return false;
          if (current.querySelector && current.querySelector('[role="button"][componentkey]')) {
            return true;
          }
          current = current.parentElement;
        }
        return false;
      },
      // LinkedIn paints the controls of the form as plain elements, so a
      // control is the innermost element that carries the text. A real button
      // wins over a painted one.
      textControls(pattern, scope) {
        const matches = Array.from(
          document.querySelectorAll('div, span, button, a[href], [role="button"]'),
        ).filter((node) => {
          if (!helpers.painted(node)) return false;
          if (node.closest('[role="button"][componentkey]')) return false;
          if (helpers.inResultsList(node, scope)) return false;
          const text = (node.innerText || node.getAttribute('aria-label') || '').trim();
          if (!pattern.test(text) || text.length > 40) return false;
          return true;
        });
        // The painted text is often a span inside the real button, and the
        // click handler lives on the button. Click the host, not the span.
        const hosted = matches.map((node) => {
          const host = node.closest('button, [role="button"], a[href]');
          if (!host || (scope && !scope.contains(host))) return node;
          const text = (host.innerText || host.getAttribute('aria-label') || '').trim();
          if (!pattern.test(text) || text.length > 60) return node;
          return host;
        });
        const controls = [...new Set(hosted)];
        // Two matches for one control (a row wrapper and its button) are one
        // control. Keep the innermost interactive element.
        const innermost = controls.filter(
          (node) => !controls.some((other) => other !== node && node.contains(other)),
        );
        innermost.sort((a, b) => {
          const rank = (node) => (node.tagName === 'BUTTON' || node.tagName === 'A' ? 0 : 1);
          if (rank(a) !== rank(b)) return rank(a) - rank(b);
          return (a.innerText || '').length - (b.innerText || '').length;
        });
        if (scope) {
          const inside = innermost.filter((node) => scope.contains(node));
          // A control outside the form is never a control of the form, even
          // when the form has none: the results list also has a "Next".
          return inside;
        }
        return innermost;
      },
      // A control of the form: the next step, the submit button.
      formButton(scope, pattern, withDisabled) {
        const usable = helpers.textControls(pattern, scope).filter((node) => {
          const disabled = node.disabled === true || node.getAttribute('aria-disabled') === 'true';
          return withDisabled ? true : !disabled;
        });
        return usable[0] || null;
      },
      // A control that sits outside the form: the apply button of the job
      // panel, or the apply button of another site.
      controlWithText(pattern) {
        const matches = Array.from(
          document.querySelectorAll('div, span, button, a[href], [role="button"]'),
        ).filter((node) => {
          if (!helpers.painted(node)) return false;
          if (node.closest('[role="button"][componentkey]')) return false;
          const aria = (node.getAttribute('aria-label') || '').trim();
          if (/filter/i.test(aria)) return false;
          const text = (node.innerText || aria || '').trim();
          if (!pattern.test(text) || text.length > 40) return false;
          return true;
        });
        const hosted = matches.map((node) => {
          const host = node.closest('button, [role="button"], a[href]');
          if (!host) return node;
          const text = (host.innerText || host.getAttribute('aria-label') || '').trim();
          if (!pattern.test(text) || text.length > 60) return node;
          return host;
        });
        const controls = [...new Set(hosted)];
        controls.sort((a, b) => {
          const rank = (node) =>
            node.tagName === 'BUTTON' || node.tagName === 'A' || node.getAttribute('role') === 'button'
              ? 0
              : 1;
          if (rank(a) !== rank(b)) return rank(a) - rank(b);
          return (a.innerText || '').length - (b.innerText || '').length;
        });
        return controls[0] || null;
      },
      // The apply form of the job, and only that one.
      applyScope() {
        const dialogs = Array.from(
          document.querySelectorAll('dialog[open], [role="dialog"]'),
        ).filter((dialog) => helpers.painted(dialog));
        const scored = dialogs
          .map((dialog) => {
            const text = dialog.innerText || '';
            const score =
              (/apply to/i.test(text) ? 1000 : 0) +
              (/submit application|\bnext\b|\breview\b/i.test(text) ? 10 : 0) +
              dialog.querySelectorAll('input, select, textarea').length;
            return { dialog, score };
          })
          .sort((a, b) => b.score - a.score);
        if (scored.length > 0 && scored[0].score > 0) return scored[0].dialog;
        const containers = Array.from(document.querySelectorAll('div, section, form')).filter((node) => {
          if (!helpers.painted(node)) return false;
          if (!/apply to/i.test(node.innerText || '')) return false;
          return helpers.textControls(/^(next|continue|review|submit application|submit|dismiss)$/i).length > 0;
        });
        containers.sort((a, b) => (a.innerText || '').length - (b.innerText || '').length);
        return containers[0] || null;
      },
});
